package com.example.simpleaccountant.ui.customers;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.simpleaccountant.R;import com.example.simpleaccountant.data.dao.CustomerDao;import com.example.simpleaccountant.data.model.Customer;
public class AddCustomerActivity extends AppCompatActivity {@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_add_customer);CustomerDao dao=new CustomerDao(this);EditText n=findViewById(R.id.etName),p=findViewById(R.id.etPhone),e=findViewById(R.id.etEmail),a=findViewById(R.id.etAddress),no=findViewById(R.id.etNote);findViewById(R.id.btnSave).setOnClickListener(v->{if(n.getText().toString().trim().isEmpty()){n.setError("Required");return;}Customer c=new Customer();c.setFullName(n.getText().toString().trim());c.setPhone(p.getText().toString().trim());c.setEmail(e.getText().toString().trim());c.setAddress(a.getText().toString().trim());c.setNote(no.getText().toString().trim());dao.insertCustomer(c);Toast.makeText(this,"Saved",Toast.LENGTH_SHORT).show();finish();});}}
